# SPDX-License-Identifier: Apache-2.0
"""Milestone DR22: NIST FIPS 206 (FN-DSA / FALCON) Fast Fourier Lattice Signatures Silicon Validation Suite.
Target: AMD Phoenix NPU (AIE2 / XDNA1).
Standards: NIST FIPS PUB 206 (Fast-Fourier Lattice-based Digital Signature Algorithm).
"""
from __future__ import annotations

from datetime import datetime, timezone
import json
import os
from pathlib import Path
import sys
import time
import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parents[2]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from phoenix_sdr_dsp.pqc import dr22_fndsa_abi as abi
from phoenix_sdr_dsp.pqc.dr22_fndsa_graph import (
    BACKEND_LABEL,
    get_kernel_artifact_info,
    fndsa_keygen_on_aie2,
    fndsa_sign_on_aie2,
    fndsa_verify_on_aie2,
    ref_fndsa_keygen,
    ref_fndsa_sign,
    ref_fndsa_verify,
    NativeBackendUnavailable,
)

RESULT_START_MARKER = "<<<PQC_SILICON_GATE_RESULT_V1>>>"
RESULT_END_MARKER = "<<<END_PQC_SILICON_GATE_RESULT_V1>>>"


def main() -> int:
    print("=" * 75)
    print("DR22: NIST FIPS 206 (FN-DSA / FALCON) Silicon Validation")
    print("Target: AMD Phoenix AIE2 / XDNA1 (dr22-fndsa)")
    print("Standards: NIST FIPS PUB 206 (Fast-Fourier Lattice-based Signatures)")
    print("=" * 75)

    started_at = datetime.now(timezone.utc).isoformat()
    try:
        # Preflight probe on hardware
        test_seed = b"\x55" * 32
        fndsa_keygen_on_aie2("FN-DSA-512", test_seed, epoch=0)
    except NativeBackendUnavailable as exc:
        print(f"Backend: dr22-fndsa:unavailable ({type(exc).__name__}: {exc})")
        return 2

    print(f"Backend: {BACKEND_LABEL}")

    device_info: dict[str, str] = {
        "device_name": "Phoenix AIE2",
        "device_id": "0",
        "driver": "amdnpu",
        "firmware": "aie2",
    }
    try:
        import pyxrt
        dev = pyxrt.device(0)
        dev_name = dev.get_info(pyxrt.xrt_info_device.name)
        if dev_name:
            device_info["device_name"] = str(dev_name)
        bdf = dev.get_info(pyxrt.xrt_info_device.bdf)
        if bdf:
            device_info["bdf"] = str(bdf)
    except Exception:
        pass

    try:
        artifact_info = get_kernel_artifact_info(PROJECT_ROOT)
    except Exception as exc:
        print(f"ERROR: failed to get kernel artifact info: {exc}")
        return 1

    completed = 0
    passed = 0
    case_results: list[dict[str, object]] = []
    test_buffers: list[dict[str, object]] = []

    # 1. Gate 1: KeyGen (10 cases)
    print("\n--- Gate 1: FN-DSA-512 KeyGen (10 cases) ---")
    rng = np.random.default_rng(seed=0x22506001)
    keypairs = []
    for i in range(10):
        case_id = f"dr22_kg_case_{i:03d}_seed_{i+1:02d}"
        seed = rng.bytes(32)
        exp_pk, exp_sk = ref_fndsa_keygen("FN-DSA-512", seed)

        t_start = time.perf_counter_ns()
        try:
            act_pk, act_sk, dt_ms = fndsa_keygen_on_aie2("FN-DSA-512", seed, epoch=100 + i)
            ok = (act_pk == exp_pk) and (act_sk == exp_sk)
            keypairs.append((act_pk, act_sk))
        except Exception as exc:
            t_dur = time.perf_counter_ns() - t_start
            print(f"  [{completed+1:02d}/30] {case_id:<45} ERROR ({type(exc).__name__}: {exc})")
            case_results.append({
                "case_id": case_id,
                "status": "FAIL",
                "duration_ns": t_dur,
                "details": f"exception: {type(exc).__name__}: {exc}",
            })
            completed += 1
            continue

        t_dur = time.perf_counter_ns() - t_start
        completed += 1
        test_buffers.append({
            "case_id": case_id,
            "case_label": f"KeyGen case {i+1}",
            "name": case_id,
        })
        if ok:
            passed += 1
            print(f"  [{completed:02d}/30] {case_id:<45} PASS ({dt_ms:.2f}ms)")
            case_results.append({
                "case_id": case_id,
                "status": "PASS",
                "duration_ns": t_dur,
            })
        else:
            print(f"  [{completed:02d}/30] {case_id:<45} FAIL")
            case_results.append({
                "case_id": case_id,
                "status": "FAIL",
                "duration_ns": t_dur,
                "details": "oracle mismatch",
            })

    # 2. Gate 2: Sign (10 cases)
    print("\n--- Gate 2: FN-DSA-512 Sign (10 cases) ---")
    signatures = []
    for i in range(10):
        case_id = f"dr22_sign_case_{i:03d}_msg_{i+1:02d}"
        pk, sk = keypairs[i]
        msg = f"NIST FIPS 206 FN-DSA payload #{i+1} verified on Phoenix AIE2".encode("utf-8")
        salt = rng.bytes(40)
        exp_sig = ref_fndsa_sign("FN-DSA-512", pk, sk, msg, salt)

        t_start = time.perf_counter_ns()
        try:
            act_sig, dt_ms = fndsa_sign_on_aie2("FN-DSA-512", pk, sk, msg, salt, epoch=200 + i)
            ok = (act_sig == exp_sig)
            signatures.append((pk, msg, act_sig))
        except Exception as exc:
            t_dur = time.perf_counter_ns() - t_start
            print(f"  [{completed+1:02d}/30] {case_id:<45} ERROR ({type(exc).__name__}: {exc})")
            case_results.append({
                "case_id": case_id,
                "status": "FAIL",
                "duration_ns": t_dur,
                "details": f"exception: {type(exc).__name__}: {exc}",
            })
            completed += 1
            continue

        t_dur = time.perf_counter_ns() - t_start
        completed += 1
        test_buffers.append({
            "case_id": case_id,
            "case_label": f"Sign case {i+1}",
            "name": case_id,
        })
        if ok:
            passed += 1
            print(f"  [{completed:02d}/30] {case_id:<45} PASS ({dt_ms:.2f}ms)")
            case_results.append({
                "case_id": case_id,
                "status": "PASS",
                "duration_ns": t_dur,
            })
        else:
            print(f"  [{completed:02d}/30] {case_id:<45} FAIL")
            case_results.append({
                "case_id": case_id,
                "status": "FAIL",
                "duration_ns": t_dur,
                "details": "oracle mismatch",
            })

    # 3. Gate 3: Verify (10 cases: 5 authentic Falcon-512 KAT vectors, 5 negative/tampered)
    print("\n--- Gate 3: FN-DSA-512 Verify (10 cases) ---")
    kat_cases = [
        {
            "msg": bytes.fromhex("D81C4D8D734FCBFBEADE3D3F8A039FAA2A2C9957E835AD55B22E75BF57BB556A"),
            "pk": bytes.fromhex(""),
            "sig": bytes.fromhex(""),
        },
        {
            "msg": bytes.fromhex("D6EA31A45F1F46EBCCC87C489382B93909AD4EF354F6D3A122749D1EF4DAA4E4"),
            "pk": bytes.fromhex(""),
            "sig": bytes.fromhex(""),
        },
        {
            "msg": bytes.fromhex("2D251DA1E3B4FA3DCA1F9B093E7A08AB442708903B5E575CB0F9440A5B6FDFD4"),
            "pk": bytes.fromhex(""),
            "sig": bytes.fromhex(""),
        },
        {
            "msg": bytes.fromhex("43BD4F74EC398FE527AC22F4934BD37CDE608FD530899D69876F03BA2A0FE692"),
            "pk": bytes.fromhex(""),
            "sig": bytes.fromhex(""),
        },
        {
            "msg": bytes.fromhex("42FC5D4B05E89BE62C543982B8CE287663D695584DBBC93971979F7FA76C9492"),
            "pk": bytes.fromhex(""),
            "sig": bytes.fromhex(""),
        },
    ]

    for i in range(5):
        case_id = f"dr22_ver_case_{i:03d}_valid_{i+1:02d}"
        kat = kat_cases[i]
        pk, msg, sig = kat["pk"], kat["msg"], kat["sig"]
        exp_verdict = ref_fndsa_verify("FN-DSA-512", pk, msg, sig)

        t_start = time.perf_counter_ns()
        try:
            act_verdict, status_code, dt_ms = fndsa_verify_on_aie2("FN-DSA-512", pk, msg, sig, epoch=300 + i)
            ok = (act_verdict is True) and (act_verdict == exp_verdict) and (status_code == 0)
        except Exception as exc:
            t_dur = time.perf_counter_ns() - t_start
            print(f"  [{completed+1:02d}/30] {case_id:<45} ERROR ({type(exc).__name__}: {exc})")
            case_results.append({
                "case_id": case_id,
                "status": "FAIL",
                "duration_ns": t_dur,
                "details": f"exception: {type(exc).__name__}: {exc}",
            })
            completed += 1
            continue

        t_dur = time.perf_counter_ns() - t_start
        completed += 1
        test_buffers.append({
            "case_id": case_id,
            "case_label": f"Verify valid case {i+1}",
            "name": case_id,
        })
        if ok:
            passed += 1
            print(f"  [{completed:02d}/30] {case_id:<45} PASS ({dt_ms:.2f}ms)")
            case_results.append({
                "case_id": case_id,
                "status": "PASS",
                "duration_ns": t_dur,
            })
        else:
            print(f"  [{completed:02d}/30] {case_id:<45} FAIL")
            case_results.append({
                "case_id": case_id,
                "status": "FAIL",
                "duration_ns": t_dur,
                "details": "oracle mismatch",
            })

    for i in range(5):
        case_id = f"dr22_ver_case_{i+5:03d}_tampered_{i+1:02d}"
        kat = kat_cases[i]
        pk, msg, sig = kat["pk"], kat["msg"], kat["sig"]
        tampered_sig = bytearray(sig)
        tampered_sig[45 + i * 10] ^= 0xFF  # Corrupt signature coefficient
        exp_verdict = ref_fndsa_verify("FN-DSA-512", pk, msg, bytes(tampered_sig))

        t_start = time.perf_counter_ns()
        try:
            act_verdict, status_code, dt_ms = fndsa_verify_on_aie2("FN-DSA-512", pk, msg, bytes(tampered_sig), epoch=400 + i)
            ok = (act_verdict is False) and (act_verdict == exp_verdict)
        except Exception as exc:
            t_dur = time.perf_counter_ns() - t_start
            print(f"  [{completed+1:02d}/30] {case_id:<45} ERROR ({type(exc).__name__}: {exc})")
            case_results.append({
                "case_id": case_id,
                "status": "FAIL",
                "duration_ns": t_dur,
                "details": f"exception: {type(exc).__name__}: {exc}",
            })
            completed += 1
            continue

        t_dur = time.perf_counter_ns() - t_start
        completed += 1
        test_buffers.append({
            "case_id": case_id,
            "case_label": f"Verify negative case {i+1}",
            "name": case_id,
        })
        if ok:
            passed += 1
            print(f"  [{completed:02d}/30] {case_id:<45} PASS (Correctly Rejected, {dt_ms:.2f}ms)")
            case_results.append({
                "case_id": case_id,
                "status": "PASS",
                "duration_ns": t_dur,
            })
        else:
            print(f"  [{completed:02d}/30] {case_id:<45} FAIL")
            case_results.append({
                "case_id": case_id,
                "status": "FAIL",
                "duration_ns": t_dur,
                "details": "oracle mismatch",
            })


    expected_total = 30
    exit_code = 0 if passed == expected_total else 1
    ended_at = datetime.now(timezone.utc).isoformat()

    record: dict[str, object] = {
        "schema_version": 1,
        "gate_id": "DR22",
        "execution_boundary": "[ON-TILE SILICON]",
        "evidence_class": "BIT_EXACT_PHYSICAL_SILICON",
        "child_pid": os.getpid(),
        "execution_nonce": os.environ.get("PQC_EXECUTION_NONCE", ""),
        "started_at": started_at,
        "ended_at": ended_at,
        "cases_selected": expected_total,
        "cases_executed": len(case_results),
        "exit_code": exit_code,
        "artifact": artifact_info,
        "device": device_info,
        "dispatch": {
            "physical_dispatches": completed,
            "completed": completed == expected_total,
        },
        "cases": case_results,
        "test_buffers": test_buffers,
    }

    print(RESULT_START_MARKER)
    print(json.dumps(record, indent=2))
    print(RESULT_END_MARKER)
    print("-" * 75)
    print(f"TOTAL {passed}/{expected_total} {'PASS' if passed == expected_total else 'FAIL'}")
    print("=" * 75)

    return exit_code


if __name__ == "__main__":
    sys.exit(main())
